#include <iostream>
#include <boost/type_index.hpp>

template<typename T>
void f(T&& param) { // Universal reference
    using boost::typeindex::type_id_with_cvr;

    // Show the exact deduced type for T
    std::cout << "T     = " << type_id_with_cvr<T>().pretty_name() << std::endl;

    // Show the exact type of the parameter
    std::cout << "param = " << type_id_with_cvr<decltype(param)>().pretty_name() << std::endl;
}

int main() {
    int x = 27;
    f(x);   // Pass lvalue
    f(42);  // Pass rvalue
}
// For f(x): T is int&, param is int&
// For f(42): T is int, param is int&&
